\usepackage{enumitem}
\usepackage{xcolor}
\usepackage{graphicx}
\usepackage{needspace}
\usepackage{microtype}
\pagestyle{empty}
\setlength{\parindent}{0pt}
\linespread{0.95}

\definecolor{accent}{RGB}{30, 90, 180}

% Section heading: title, then a rule underneath; never alone at a page foot
\newcommand{\sect}[1]{%
  \par\needspace{4\baselineskip}%
  \vspace{0.5em}%
  {\bfseries\large\color{accent} #1}\par\nointerlineskip\vspace{2pt}%
  {\color{accent}\rule{\linewidth}{1.2pt}}\par\vspace{0.25em}%
}
\newcommand{\sectsub}[1]{\par\needspace{3\baselineskip}{\small\bfseries #1}\par}

% \job{title}{dates}{organisation}{location}
\newcommand{\job}[4]{%
  \par\needspace{3\baselineskip}%
  {\bfseries #1}\hfill{\small\itshape\color{gray}#2}\\*%
  {\small\color{gray}#3\ifx&#4&\else{} \textbullet{} #4\fi}%
}

\begin{document}

\begin{minipage}[c]{1.0\linewidth}
  {\fontsize{25}{27}\selectfont\bfseries\color{accent} Camille Moreau}\\[0.3em]
  {\large Docteure en statistique, data scientist}\\[0.35em]
  \small \mbox{\href{mailto:camille.moreau@exemple.fr}{camille.moreau@exemple.fr}} \enspace\textbar\enspace \mbox{\href{tel:+33612345678}{+33 6 12 34 56 78}} \enspace\textbar\enspace \mbox{Lyon, France}\\[0.15em]
  \mbox{\href{https://linkedin.com/in/camille-moreau}{linkedin.com/in/camille-moreau}} \enspace\textbar\enspace \mbox{\href{https://github.com/cmoreau}{github.com/cmoreau}}
\end{minipage}

\vspace{0.4em}
{\color{accent}\rule{\linewidth}{1.8pt}}

\sect{Profil}
{\small Statisticienne spécialisée dans les séries temporelles et la prévision de la demande ; six ans d'expérience entre recherche publique et industrie.\par}

\sect{Compétences}
{\small
\textbf{Programmation:} Python, R, SQL\\[2pt]
\textbf{Outils:} Git, Docker, Airflow, MLflow\\[2pt]
\textbf{Langues:} Français (langue maternelle), anglais (C1), espagnol (B1)
\par}

\sect{Expérience professionnelle}

\job{Data scientist senior}{mars 2022 -- aujourd'hui}{Enedis}{Lyon}
\begin{itemize}[noitemsep, topsep=3pt, leftmargin=1.2em]
  \item Réduit de 18 \% l'erreur de prévision journalière sur 35 millions de compteurs
  \item Encadre une équipe de 4 data scientists et 2 alternants
  \item Mis en production un pipeline de prévision suivi en continu (MLflow, Airflow)
\end{itemize}

\vspace{0.3em}
\job{Ingénieure de recherche}{janv. 2021 -- févr. 2022}{Inria}{Grenoble}
\begin{itemize}[noitemsep, topsep=3pt, leftmargin=1.2em]
  \item Développé une bibliothèque Python open source de prévision probabiliste (1 200 étoiles sur GitHub)
\end{itemize}

\sect{Formation}

\job{Doctorat en mathématiques appliquées}{oct. 2017 -- déc. 2020}{Université Claude Bernard Lyon 1}{Lyon}
\begin{itemize}[noitemsep, topsep=3pt, leftmargin=1.2em]
  \item Thèse : modèles bayésiens hiérarchiques pour la prévision de consommation électrique
\end{itemize}

\vspace{0.3em}
\job{Master Statistique et science des données}{sept. 2015 -- juin 2017}{ENSAI}{Rennes}

\sect{Publications}
\sectsub{Articles de revues}
\begin{enumerate}[leftmargin=*, itemsep=2pt, topsep=3pt]
  \item \textbf{Moreau, C.}, Durand, P. \& Lefèvre, H. (2022). \foreignlanguage{english}{Hierarchical forecasting of electricity demand: a Bayesian approach}. \textit{International Journal of Forecasting}.
\end{enumerate}
\sectsub{Actes de conférences}
\begin{enumerate}[leftmargin=*, itemsep=2pt, topsep=3pt]
  \item \textbf{Moreau, C.} \& Bernard, T. (2021). Prévision probabiliste de la consommation : une étude comparative. \textit{Journées de statistique de la SFdS}.
\end{enumerate}

\sect{Enseignement et encadrement}
\begin{itemize}[noitemsep, topsep=2pt, leftmargin=1.2em]
  \item 2018 – 2020 : travaux dirigés de probabilités, licence 2 (64 h par an)
\end{itemize}

\sect{Prix et distinctions}
\begin{itemize}[noitemsep, topsep=2pt, leftmargin=1.2em]
  \item 2021 : prix de thèse de la Société française de statistique
\end{itemize}

\end{document}

